async () => {
  const frame = () => new Promise((resolve) => requestAnimationFrame(() => resolve(performance.now())));
  const el = (id) => document.querySelector(`[data-testid="${id}"]`);
  const cards = () => document.querySelectorAll('[data-testid="card-pool"] .db-card').length;
  const whole = () => el("db-result-count") !== null && cards() === Number(el("db-result-count").getAttribute("data-count"));
  const median = (xs) => Math.round([...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)]);
  const until = async (test, start) => {
    let last = start, longest = 0;
    while (!test()) { const now = await frame(); longest = Math.max(longest, now - last); last = now; }
    return [performance.now() - start, longest];
  };
  const runs = { openFirst: [], openWhole: [], openLongest: [], narrowLongest: [], clearFirst: [], clearWhole: [], clearLongest: [], detail: [] };
  for (let run = 0; run < 5; run += 1) {
    if (el("site-footer-almanac") === null) { el("nav-back").click(); await until(() => el("site-footer-almanac") !== null, performance.now()); }
    await frame(); await frame();
    const start = performance.now();
    el("site-footer-almanac").click();
    const [first, gap] = await until(() => cards() > 0, start);
    const [all, gap2] = await until(whole, start);
    if (run > 0) { runs.openFirst.push(first); runs.openWhole.push(all); runs.openLongest.push(Math.max(gap, gap2)); }
  }
  const search = async (value) => {
    await frame(); await frame();
    const input = el("db-search");
    const start = performance.now();
    Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set.call(input, value);
    input.dispatchEvent(new Event("input", { bubbles: true }));
    const next = await frame();
    const [, gap] = await until(whole, next);
    return [next - start, performance.now() - start, Math.max(next - start, gap)];
  };
  for (let run = 0; run < 5; run += 1) {
    runs.narrowLongest.push((await search("dra"))[2]);
    const [first, all, gap] = await search("");
    runs.clearFirst.push(first); runs.clearWhole.push(all); runs.clearLongest.push(gap);
    await frame(); await frame();
    const start = performance.now();
    document.querySelectorAll(".db-card")[run * 3].click();
    runs.detail.push((await until(() => el("inspect-detail") !== null, start))[0]);
    el("inspect-close").click();
    await until(() => el("inspect-detail") === null, performance.now());
  }
  const pool = el("card-pool");
  pool.scrollTop = 0;
  await frame(); await frame();
  const gaps = [];
  let last = await frame();
